#!/usr/bin/env python3
"""Check dated source metadata consistency and data-minimization boundaries."""
import argparse,csv,io,json,pathlib,datetime
from build_results import DECISIONS

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--repo',default='.');a=ap.parse_args();o=pathlib.Path(a.repo)/'updates/2026-10-31/scan';checks=[]
 def check(name,v):assert v,name;checks.append(name)
 def j(p):return json.loads((o/p).read_text())
 def lines(p):return list(map(json.loads,(o/p).read_text().splitlines()))
 s=j('summary.json');raw=j('search-log.json');req=j('request-log.json');pub=lines('pubmed-screening.jsonl');reg=lines('registry-evidence.jsonl');primary=lines('primary-evidence.jsonl')[0];prism=j('prism-protocol-summary.json')
 check('date',s['date']=='2026-10-31');check('prior cutoff',s['strict_prior_cutoff_utc']=='2026-10-30T02:51:17.233943+00:00');check('actual interval',s['core_started_utc']<s['core_completed_utc']);check('24 unique PubMed',len(pub)==len({x['pmid'] for x in pub})==24);check('reviewed identifier set',set(DECISIONS)=={x['pmid']for x in pub});check('eight queries',len(raw['pubmed']['queries'])==8);check('32 occurrences',sum(q['count']for q in raw['pubmed']['queries'])==s['pubmed_id_occurrences']==32);check('queries complete',all(q['count']==len(q['ids'])<1000 for q in raw['pubmed']['queries']));check('query IDs equal records',set(i for q in raw['pubmed']['queries']for i in q['ids'])=={x['pmid']for x in pub});check('prior overlap',sum(x['prior_scan_overlap']for x in pub)==s['pubmed_previous_day_overlap']==12);check('abstracts not retained',all(x['abstract_retained'] is False and 'abstract'not in x for x in pub));check('one newly extracted older primary',sum(x['new_to_repository_primary_record']for x in pub)==1);check('no new first publications',not any(x['new_publication_since_prior_cutoff']for x in pub));check('41 core requests',len(req)==41);check('requests succeeded',all(x.get('status')==200 and 'error'not in x for x in req));check('preprint servers',{x['server']for x in raw['preprints']}=={'biorxiv','medrxiv'});n=0
 for p in raw['preprints']:
  idx=list(csv.DictReader(io.StringIO((o/p['index_path']).read_text()),delimiter='\t'));check(p['server']+' unique/count',len(idx)==len({(x['doi'],x['version'])for x in idx})==p['unique_doi_versions']);check(p['server']+' complete',p['pagination_complete_for_observed_response'] and len(p['reported_totals'])==1 and p['reported_totals'][0]==len(idx));check(p['server']+' zero hits',not p['matches']);n+=len(idx)
 check('684 versions',n==s['preprint_doi_versions']==684);check('registry no paging',all(not q['response'].get('nextPageToken')for q in raw['registry']));check('five selected registries',len(reg)==5);check('registry no results',not any(x['hasResults']for x in reg));check('new protocol only one',s['new_registry_protocols']==['NCT07905898']);check('new protocol not efficacy',prism['evidence_type']=='new official registry protocol, no results');check('denominator distinction',prism['planned_total_enrollment_field']==95 and prism['detailed_adolescent_enrollment']==85 and prism['phase_counts']['randomized_pilot']==60);check('HRH3 date before cutoff',primary['electronic_publication_date']=='2026-10-20' and primary['new_publication_after_prior_cutoff'] is False);check('HRH3 aggregate estimates',primary['results']=={'HRH3_eta_squared':0.035,'HRH3_p':0.033,'HRH3_BF10':2.96,'HRH4_exploratory_BF10':1.20});check('negative evidence retained','No other'in primary['negative_evidence']);check('primary abstract limit','abstract-only'in primary['evidence_type']);check('old retraction controls unchanged',all(not x['selected_metadata_changed_fields']for x in j('integrity-recheck.json')));check('ISRCTN zero window',j('supplement-selected-metadata.json')['window']['root_attributes']['totalCount']=='0');check('WHO coverage limitation',not j('supplement-selected-metadata.json')['who_ictrp']['query_export_obtained']);check('CTIS coverage limitation',not j('supplement-selected-metadata.json')['ctis']['parsed_trial_record']);
 for x in reg:check(x['id']+' no contact/result fields',not any(t in json.dumps(x) for t in ['contactsLocationsModule','resultsSection','individualParticipantData']))
 out={'checkedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'passed':len(checks),'checks':checks,'interpretation':'Consistency and data-minimization checks, not independent clinical validation.'};(o/'validation.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
if __name__=='__main__':main()
